\label{th:estimation-guarantee}
	Suppose $\alpha\in(0,1)$ and  $n\geq C(\log(1/\alpha)+d)$ for a sufficiently large $C > 0$. Simultaneously for all $t\in\left[1.6, \Phi^{-1}\left(1 - 300 \sqrt{ \frac{d}{n} } - \sqrt{ \frac{\log(1/\alpha)}{n} } \right)\right]$ and for all $u \in \mathcal{S}^{d-1}$,
\begin{equation} \label{ineq:upper-side}
	\widehat{\theta}^u(t)-\theta^\top u\leq \frac{2}{t},
\end{equation}
with $P_{\epsilon, \theta, Q}$-probability at least $1-\alpha$, uniformly over all $\epsilon\in[0,0.05]$, all $\theta\in\mathbb{R}^d$, and all $Q$. Moreover, set 
\begin{equation} 
		t_{\epsilon} = \Phi^{-1}\left( 1- \epsilon - 300 \sqrt{ \frac{d}{n} } - \sqrt{ \frac{\log(1/\alpha)}{n} }  \right), \label{def:t-constant}
\end{equation} and then simultaneously for all $u \in \mathcal{S}^{d-1}$,
\begin{equation}
\widehat{\theta}^u(t_{\epsilon})-\theta^\top u \geq 0, \label{eq:the-other-side}
\end{equation}
with $P_{\epsilon, \theta, Q}$-probability at least $1-\alpha$, uniformly over all $\epsilon\in[0,0.05]$, all $\theta\in\mathbb{R}^d$ and all $Q$.

\label{thm:upper-bound-general-Gaussian}
There exist universal constants $C,C'>0$, such that for any $\alpha\in(0,1)$ and $n\geq C(\log(1/\alpha)+d)$, the set $\widehat{{\textnormal{CS}}}$ defined in (\ref{eq:adaptive-CI}) satisfies
	\begin{equation*}
		\begin{split}
			&\inf_{ \epsilon \in [0, 0.05], \theta, Q} P_{\epsilon, \theta, Q}\left( \theta \in\widehat{{\textnormal{CS}}}\right) \geq 1-\alpha,\\
			&\inf_{\epsilon \in [0, 0.05], \theta, Q } P_{\epsilon, \theta, Q}\left( |\widehat{{\textnormal{CS}}}| \leq C' \left(\frac{1}{\sqrt{\log (n/d )} }+\frac{1}{\sqrt{ \log(1/\epsilon) }}+ \frac{1}{\sqrt{ \log(n/\log(1/\alpha)) }} \right) \right) \geq 1-\alpha.
		\end{split}
	\end{equation*}

\label{th:lower-bound-Gaussian} There exist universal constants $c, C$ such that for any $\alpha \in (0,1/4)$ and for any $n \geq C (d + \log(1/\alpha))$,
\begin{equation} \label{ineq:r-stat-lower}
	r_{\alpha}(\epsilon, 0.05) \geq c \left( \frac{1}{\sqrt{\log (n/d)}}+ \frac{1}{\sqrt{\log(1/\epsilon)}}+ \frac{1}{\sqrt{ \log(n/\log(1/\alpha)) }} \right),
\end{equation}
for any $\epsilon\in[0,0.05]$.

\label{prop:CI-imply-test-new}
Suppose $\widehat{{\textnormal{CS}}}$ is a confidence set that satisfies
\begin{equation*}
		\begin{split}
			\textnormal{(coverage)} &\quad \inf_{\theta, Q} P_{0.05, \theta, Q}\left( \theta \in\widehat{{\textnormal{CS}}}\right) \geq 1-\alpha,\\
			\textnormal{(diameter at } \epsilon = 0) & \quad P_{0}\left( |\widehat{{\textnormal{CS}}}| < r  \right) \geq 1-\alpha,
		\end{split}
	\end{equation*} where $P_0 = N(0,I_d)$.
Then, the testing function $\phi$ defined in (\ref{eq:reverse-t-new}) satisfies the following Type-1 and Type-2 error control:
\begin{equation*}
		\begin{split}
			 &  P_{0}\left(\phi=1\right) + \sup_{Q, u\in \mathcal{S}^{d-1}} P_{0.05, ru,Q}\left(\phi=0\right)\leq 3\alpha.
		\end{split}
	\end{equation*}

\label{prop:test-lower-bound-gaussian}
There exist universal constants $C,c>0$ such that for any $\alpha \in (0,0.05)$ and $n \geq C\left(d + \log(1/\alpha) \right)$,
	we have
		\begin{equation} \label{ineq:testing-lower-bound-claim}
			\inf_{\phi} \left\{ P_{0 } \left( \phi = 1 \right) + \sup_{Q, u\in \mathcal{S}^{d-1}} P_{0.05, ru,Q}\left(\phi=0\right) \right\} \geq 4\alpha,
		\end{equation}
        with $r = c \left(\frac{1}{\sqrt{ \log(n/\log(1/\alpha)) }} + \frac{1}{\sqrt{\log (n/d)}} \right)$.

\label{lm:NGCA-stat}
	Suppose $\alpha \in (0,0.05)$ and the non-Gaussian component distribution $A$ satisfies $\int x A(x) dx = 0$ and $ \chi^2(A, N(0,1)) \leq \frac{d + \log(1/\alpha)}{8n} $. Then,
\begin{equation*}
	\inf_{\phi} \left\{ P_0(\phi = 1) + P_{\mu}(\phi = 0) \right\} \geq 4\alpha,
\end{equation*}
where $P_0=N(0,I_d)^{\otimes n}$ and $P_{\mu} = \int (P_u^A)^{\otimes n} d\mu(u)$ with $\mu$ being the uniform measure on $\mathcal{S}^{d-1}$.

\label{def:vstat}
	Let $P$ be a distribution over a domain $\mathcal{X}$. A statistical query is a bounded function $q: \mathcal{X} \to [-1, 1]$. We define 
	$\mathtt{STAT}_{P, \tau}$ to be an oracle that, given any statistical query $q$, outputs a value $v = \mathtt{STAT}_{P, \tau}(q)$ satisfying $|v - \mathbb{E}_{X \sim P}[q(X)]| \leq \tau$, where $\tau \in (0,1)$ is the tolerance parameter of the SQ oracle.

\label{def:SQCS}
Given some $\epsilon\in[0,\epsilon_{\max}]$, we say that an SQ algorithm $\widehat{{\textnormal{CS}}}$ is an adaptive robust confidence set with $k$ queries, tolerance $\tau$, and diameter $r$ at contamination level $\epsilon$, if $\widehat{{\textnormal{CS}}}\in \mathrm{SQ}(k,\tau)$ and
\begin{eqnarray*}
\inf_{\theta}\inf_{P \in \mathcal{P}_{\epsilon_{\max},\theta} } \,  \,\inf_{\mathtt{STAT}_{P,\tau} \in \mathtt{Oracle}_{P,\tau} } \mathbb{P}\left( \theta \in \widehat{{\textnormal{CS}}}(\mathtt{STAT}_{P,\tau})\right) \geq 0.95, \\
\inf_{\theta}\inf_{P \in \mathcal{P}_{\epsilon,\theta} } \inf_{\mathtt{STAT}_{P,\tau} \in \mathtt{Oracle}_{P,\tau}} \mathbb{P} \left( |\widehat{{\textnormal{CS}}}(\mathtt{STAT}_{P,\tau})| < r \right) \geq 0.95,
\end{eqnarray*}
where the probability is taken over the randomness of the algorithm.

\label{th:SQ-lower-bound}
Let $\epsilon\in[0,0.05]$. There exist universal constants $c,c_1$ such that for any $0<m\leq d^{c}$, any SQ confidence set $\widehat{{\textnormal{CS}}}\in \mathrm{SQ}(k,\tau)$ (Definition \ref{def:SQCS}) with diameter $r$ at contamination level $\epsilon$ satisfying
$$r\leq \frac{c_1}{\sqrt{m}}$$
must require either
	\begin{equation} \label{ineq:SQ-option}
		\begin{split}
			&\text{(i) number of queries  }k \geq 2^{d^{\Omega(1)}}, \text{ or }\\
			&\text{(ii) tolerance of the SQ oracle } \tau =d^{- \Omega(m)}. 
		\end{split}
	\end{equation}

\label{def:SQtest}
Let $P_0$ be a distribution and let $\mathcal{P}$ be a collection of distributions over a common support such that $P_0\notin \mathcal{P}$. We say that an SQ algorithm $\mathcal{A}$ solves the testing problem
\[
H_0: P=P_0
\qquad\text{versus}\qquad
H_1: P\in\mathcal{P}
\]
with $k$ queries and tolerance $\tau$ if $\mathcal{A}\in\mathrm{SQ}(k,\tau)$ and
\[
\sup_{P\in\{P_0\}\cup\mathcal{P}}
\sup_{\mathtt{STAT}_{P,\tau}\in\mathtt{Oracle}_{P,\tau}}
\mathbb{P}
\left(
\mathcal{A}(\mathtt{STAT}_{P,\tau})
\neq
{\mathds{1}}\{P\neq P_0\}
\right)
\le 0.1,
\]
where the probability is taken over the randomness of the algorithm.

\label{lm:SQ-CS-testing}
For any $\epsilon\in[0,\epsilon_{\max}]$, suppose there exists an SQ confidence set with diameter $r$, $k$ queries, and tolerance $\tau$ in the sense of Definition \ref{def:SQCS}. Then there exists an SQ test that solves the testing problem
\begin{equation}
P_0=N(0,I_d)
\qquad\text{versus}\qquad
\mathcal{P}
=
\left\{
(1-\epsilon_{\max})N(ru,I_d)+\epsilon_{\max}Q
:
Q,\;
u\in\mathcal{S}^{d-1}
\right\} \label{eq:SQ-test-CI}
\end{equation}
in the sense of Definition \ref{def:SQtest}, with the same number of queries $k$ and tolerance $\tau$.

\label{lm:SQ-NGCA}
Consider the testing problem
\begin{equation}
P_0=N(0,I_d)
\qquad\text{versus}\qquad
\mathcal{P}
=
\left\{
P_u^A
:
u\in\mathcal{S}^{d-1}
\right\}, \label{eq:NGCA-SQ}
\end{equation}
and let $m\leq d^{c}$ be a nonnegative integer where $c> 0$ is sufficiently small.
Suppose the distribution $A$ matches the first $m$ moments of $N(0,1)$. Then, every SQ
algorithm that solves the testing problem with $k$ queries and tolerance $\tau$ in the sense of Definition \ref{def:SQtest} must satisfy either
	\begin{equation} \label{ineq:SQ-option-NGCA}
		\begin{split}
			&\text{(i)  number of queries }k \geq 2^{d^{\Omega(1)}}, \text{ or }\\
			&\text{(ii)  tolerance of the SQ oracle  } \tau =d^{-\Omega(m)}. 
		\end{split}
	\end{equation}

\label{thm:finite-sample-analysis}
There exist universal constants $C,C'>0$, such that for any $\alpha\in(0,1)$ and $n=\lceil d^m\rceil\geq C/\alpha^4$, as long as the pilot estimator $\widehat{\theta}$, which is independent of the observations, satisfies
\begin{equation}
\inf_{\epsilon\in[0,0.05],\theta,Q}P_{\epsilon,\theta,Q}\left(\|\widehat{\theta}-\theta\|\leq C\left(\sqrt{\frac{d}{n}}+\epsilon + \sqrt{\frac{\log(1/\alpha)}{n}}\right)^{0.1}\right) \geq 1-\frac{\alpha}{6}, \label{eq:pilot}
\end{equation}
the confidence set $\widehat{{\textnormal{CS}}}$ output by Algorithm \ref{alg:ARCS} satisfies
	\begin{equation*}
		\begin{split}
			 &\quad \inf_{ \epsilon \in [0, 0.05], \theta, Q} P_{\epsilon, \theta, Q}\left( \theta \in\widehat{{\textnormal{CS}}} \right) \geq 1-\alpha,\\
			 & \quad\inf_{\epsilon \in [0, 0.05], \theta, Q } P_{\epsilon, \theta, Q}\left( |\widehat{{\textnormal{CS}}}| \leq C' \left(\frac{1}{\sqrt{\log (n/d )} }+\frac{1}{\sqrt{ \log(1/\epsilon) }}+ \frac{1}{\sqrt{ \log(n/\log(1/\alpha)) }} +\frac{1}{\sqrt{m}}\right)\right) \geq 1-\alpha.
		\end{split}
	\end{equation*}

\label{lm:structural-result}
		Given any probability measures $P_1, P_2, Q$ supported on the common measurable space $(\Omega, \mathcal{F})$, and any function class $\mathcal{H}$ consisting of functions defined on $\Omega$. For any $\delta \in [0,1/4],\epsilon \in [0,1/4]$, if there exists a probability distribution $D$ on $(\Omega, \mathcal{F})$ such that
		\begin{equation*}
			(i) \, \, (1 - \epsilon) P_1 + \epsilon Q \geq (1 - \delta) D \quad \text{ and }\quad (ii)\,\, \int_{\Omega} h(x) d D(x) = \int_{\Omega} h(x) d P_2 (x) \text{ for all } h \in \mathcal{H},
		\end{equation*} then for any nonnegative $h \in \mathcal{H}$, 
		\begin{equation*}
			\int_{\Omega} h(x) d P_2 (x) \geq \frac{2}{3} \inf \left\{ \int_{\Omega} h(x) dD' (x): D' \text{ is a distribution such that } P_1 \geq \left( 1- \frac{4\delta}{3} \right)D' \right\}.
		\end{equation*}

\label{lm:population-existence-analysis}
	Suppose $u$ is a fixed unit vector in $\mathbb{R}^d$. Then given any $r\in [0, 1]$, any $\delta \in [ \sqrt{r} , 1]$ and any nonnegative integer $m \leq \frac{\delta^2}{256 r^2}$, there exists a multivariate distribution $D$ supported on $\mathbb{R}^d$ such that
	\begin{equation} \label{eq:original-program-popu}
		\begin{split}
			\quad &  D \geq (1 - \delta) N(ru, I_d),\quad  N(ru, I_d) \geq (1 - \delta )D \quad \text{ and }\quad  D\equiv_{m}N(0,I_d).
		\end{split}
	\end{equation}

\label{eq:assump-concentration}
	 Assume $ d, m$ are positive integers. Suppose the distribution $D$ supported on $\mathbb{R}^d$ satisfies that $\mathbb{E}_D[p(X)] = \mathbb{E}_{N(0, I_d)}[p(X)]$ for any polynomial $p \in \mathcal{P}_{2m,d}$. Let $X_1, \ldots, X_{n}$ be i.i.d. samples drawn from $D$. Then with probability at least $1 - \alpha$  
\begin{equation} \label{ineq:D-concentration}
	\sup_{p \in \mathcal{F}_{m, d} }\left|\frac{1}{n} \sum_{i=1}^n p(X_i) - \mathbb{E}_{N(0,I_d)}[p(X)]\right| \leq 2(1 + 1/\alpha) \sqrt{ \frac{N}{n} },
\end{equation} where $N = {d+m \choose m}$ and $\mathcal{F}_{m,d} = \{p \in \mathcal{P}_{m,d}: \mathbb{E}_{N(0, I_d)}[p^2(X)] = 1 \}$.

\label{lm:gaussian-tail} Suppose $m$ is an even positive integer. 
	\begin{enumerate}
		\item[(i)] Then $\mathbb{E}_{N(0,1)}[X^m] = (m-1)!! = \sqrt{\frac{2}{\pi}} \int_{0}^{\infty} x^m  {\rm{exp}}(-x^2/2) dx \in \left[ \frac{\sqrt{2}}{e} (m/e)^{m/2}, \sqrt{2}e (m/e)^{m/2} \right]$.
		\item[(ii)] For any $m \geq 20$ and $t \geq \sqrt{2m}$, $\int_{\sqrt{m/e}}^{t} x^m  {\rm{exp}}(-x^2/2) dx \geq \frac{\sqrt{\pi}}{2e} (m/e)^{m/2}$.
		\item[(iii)] Given any $r > 0$, we have $\mathbb{E}_{N(r,1)}[X^m] \leq 2 {\rm{exp}}(3r\sqrt{m}/2) (m/e)^{m/2}$.
		\item[(iv)] Given any $r > 0$, denote the CDF of $X^m$ where $X \sim N(r,1)$ as $F(\cdot)$. For any $m \geq 20$, any $\delta \in (0,1/2)$, when $\Phi^{-1}(1 - \delta/2) - r \geq \sqrt{2m}$, we have
		\begin{equation*}
			\mathbb{E}_{N(r,1)}[X^m {\mathds{1}}(X^m \leq F^{-1}(1 - \delta))] \geq  \frac{1}{2\sqrt{2}e} {\rm{exp}}(-r^2/2 + r \sqrt{m/e}) (m/e)^{m/2}.
		\end{equation*}

	\end{enumerate}

{\bf Proof of Part (i).} The first equality in (i) is a standard fact. Moreover, by the equality $(m-1)!! = \frac{m!}{2^{m/2} (m/2)!} $ and the bound for the factorial \citep{robbins1955remark},
	\begin{equation*}
		\sqrt{2\pi m} (m/e)^m \leq m! \leq e\sqrt{2\pi m} (m/e)^m,
	\end{equation*} we get $(m-1)!! \in \left[ \frac{\sqrt{2}}{e} (m/e)^{m/2}, \sqrt{2}e (m/e)^{m/2} \right]$.

	{\bf Proof of Part (ii).} 
	In view of what we have proved in Part (i), to show the second statement, we just need to show 
	\begin{subequations}
		\begin{align}
			&\int^{\sqrt{m/e}}_0 x^m  {\rm{exp}}(-x^2/2)dx \leq\frac{1}{4} \frac{\sqrt{\pi}}{e} (m/e)^{m/2}, \label{ineq:lower-tail}\\
			&\int_{t}^{\infty} x^m  {\rm{exp}}(-x^2/2)dx\leq\frac{1}{4} \frac{\sqrt{\pi}}{e} (m/e)^{m/2}. \label{ineq:upper-tail}
		\end{align}
	\end{subequations}

First, notice that $x^m {\rm{exp}}(-x^2/2) = {\rm{exp}}( -x^2/2 + m \log x )$ and this function increases when $x \in [0, \sqrt{m}]$ and decreases when $x \geq \sqrt{m}$. Thus
	\begin{equation*}
		\begin{split}
			\int^{\sqrt{m/e}}_0 x^m  {\rm{exp}}(-x^2/2)dx \leq \sqrt{m/e} (m/e)^{m/2} {\rm{exp}}(-m/(2e)) &\overset{(a)}\leq \frac{1}{4} \frac{\sqrt{\pi}}{e} (m/e)^{m/2}, 


		\end{split}
	\end{equation*} where (a) holds whenever $m \geq 20$.

	Next,
	\begin{equation*}
		\begin{split}
			\int_{t}^{\infty} x^m  {\rm{exp}}(-x^2/2)dx &\leq \sup_{x \geq t} \{x^m {\rm{exp}}(-x^2/4) \} \int_{t}^{\infty} {\rm{exp}}(-x^2/4) dx  \overset{(a)}\leq (\sqrt{2m})^{m} {\rm{exp}}(-m/2)  \int_{t}^{\infty} {\rm{exp}}(-x^2/4) dx\\
			& \overset{(b)}\leq 2(2m/e)^{m/2} {\rm{exp}}(-t^2/4) \overset{(c)}\leq 2(2m/e)^{m/2} {\rm{exp}}(-m/2) = 2(\frac{2m}{e^2} )^{m/2}\\
			& \leq \frac{1}{4} \frac{\sqrt{\pi}}{e} (m/e)^{m/2},                                                                                                              
		\end{split}
	\end{equation*} where (a) is because ${\rm{exp}}(m \log x -x^2/4)$ is increasing when $x \in [0, \sqrt{2m}]$ and decreasing when $x \geq \sqrt{2m}$; (b) is because of the Gaussian tail integration bound, see Theorem 1.2.3 in \cite{durrett2019probability}; (c) is because $t \geq \sqrt{2m}$ and $m \geq 20$. 

{\bf Proof of Part (iii).} 
\begin{equation} \label{ineq:shift-normal-mean-up}
	\begin{split}
		\mathbb{E}_{N(r,1)}[X^m] &= \int_{-\infty}^{\infty} x^m \phi(x-r) dx \leq 2 \int_{0}^{\infty} x^m \phi(x-r) dx \\
		& = \frac{2}{\sqrt{2\pi}} {\rm{exp}}(-r^2/2) \int_{0}^{\infty} {\rm{exp}}(-x^2/2 + xr + m \log x ) dx.
	\end{split}
\end{equation} Let $f(x) = -x^2/2 + xr + m \log x$, then $f'(x) = -x + r + m/x$ and $f''(x) = -1 - m/x^2 \leq -1$. Notice that $f'(x)$ has a positive root $x^* = \frac{r + \sqrt{r^2 + 4m} }{2} $. So, by a Taylor expansion, we have for all $x \geq 0$, $f(x) \leq f(x^*) - \frac{1}{2} (x - x^*)^2$ and at the same time,
\begin{equation*}
\begin{split}
	f(x^*) &  = -m + \frac{x^{*2}}{2} + m \log(x^*)\\
	& = -\frac{m}{2} + \frac{1}{4}r \sqrt{r^2 + 4m} + \frac{r^2}{4} + m \log\left( \frac{r + \sqrt{r^2 + 4m}}{2} \right) \\
	& \leq -\frac{m}{2}+\frac{r^2}{2} + \frac{r\sqrt{m}}{2} + m \log(\sqrt{m} + r) \quad(\text{since} \sqrt{a+b} \leq \sqrt{a} + \sqrt{b})\\
	& \leq  -\frac{m}{2}+ m \log \sqrt{m} +\frac{r^2}{2} + \frac{3r\sqrt{m}}{2}.
\end{split}
\end{equation*} By plugging the above inequalities into \eqref{ineq:shift-normal-mean-up},
\begin{equation*}
	\begin{split}
		\mathbb{E}_{N(r,1)}[X^m] &\leq  \frac{2}{\sqrt{2\pi}} {\rm{exp}}(-r^2/2) \int_{0}^{\infty} {\rm{exp}}\left(  -\frac{m}{2}+ m \log \sqrt{m}+ \frac{r^2}{2} + \frac{3r\sqrt{m}}{2} - \frac{1}{2} (x - x^*)^2 \right) dx \\
		& \leq 2 {\rm{exp}}(3r\sqrt{m}/2)  (m/e)^{m/2}.
	\end{split}
\end{equation*} 

{\bf Proof of Part (iv).} Let $t = F^{-1}(1 - \delta)$. Then by definition, $\mathbb{P}_{N(r,1)} \left( X^m \geq t  \right) = \delta$. Since $\delta \in (0,1/2)$, $t^{1/m} \geq r$. This means that 
\begin{equation} \label{ineq:t-range}
\begin{split}
\mathbb{P}_{N(0,1)}((X+r)^m \geq t )= \delta  &\Longrightarrow \mathbb{P}_{N(0,1)}(|X| \leq t^{1/m}- r) \leq 1 - \delta \text{ and } \mathbb{P}_{N(0,1)}(|X| \leq t^{1/m}+ r) \geq 1 - \delta \\
	&  \Longleftrightarrow \Phi^{-1}(1 - \delta/2) - r \leq t^{1/m} \leq \Phi^{-1}(1 - \delta/2) + r.
\end{split}	
\end{equation} Thus,
\begin{equation*}
	\begin{split}
		\mathbb{E}_{N(r,1)}[X^m {\mathds{1}}(X^m \leq F^{-1}(1 - \delta))] & = \int^{t^{1/m}}_{-t^{1/m}} x^m \phi(x - r) d x \\
		& = \frac{1}{\sqrt{2 \pi}} {\rm{exp}}(-r^2/2) \int^{t^{1/m}}_{-t^{1/m}} x^m {\rm{exp}}(-x^2/2 + xr) d x \\
		& \geq  \frac{1}{\sqrt{2 \pi}} {\rm{exp}}(-r^2/2) \int^{t^{1/m}}_{0} x^m {\rm{exp}}(-x^2/2 + xr) d x \\
		& \overset{ \eqref{ineq:t-range} }\geq  \frac{1}{\sqrt{2 \pi}} {\rm{exp}}(-r^2/2) \int^{\Phi^{-1}(1 - \delta/2) - r }_{0} x^m {\rm{exp}}(-x^2/2 + xr) d x \\
		& \geq \frac{1}{\sqrt{2 \pi}} {\rm{exp}}(-r^2/2) \int^{\Phi^{-1}(1 - \delta/2) - r }_{\sqrt{m/e}} x^m {\rm{exp}}(-x^2/2 + xr) d x \\
		& \geq \frac{1}{\sqrt{2 \pi}} {\rm{exp}}(-r^2/2 + r \sqrt{m/e}) \int^{\Phi^{-1}(1 - \delta/2) - r }_{\sqrt{m/e}} x^m {\rm{exp}}(-x^2/2) d x \\
		& \overset{(a)}\geq  \frac{1}{2\sqrt{2}e} {\rm{exp}}(-r^2/2 + r \sqrt{m/e}) (m/e)^{m/2} \;,
	\end{split}
\end{equation*} where (a) holds since $\Phi^{-1}(1 - \delta/2) - r \geq \sqrt{2m}$ and Lemma \ref{lm:gaussian-tail} (ii).
This finishes the proof.

\label{lm:DKW}
	Suppose $n$ is a positive integer. Let $X_1, \ldots, X_n$ be i.i.d.\ real-valued random variables drawn from a distribution with CDF $F(\cdot)$. Then for any $\alpha \in (0,1)$,
	\begin{equation*}
		\mathbb{P}\left( \sup_{t \in \mathbb{R}} |F_n(t) - F(t)| > \sqrt{ \frac{\log(2/\alpha)}{2n} } \right) \leq \alpha,
	\end{equation*}where $F_n(\cdot)$ is the empirical CDF.

\label{lm:multi-DKW}
	Suppose $n$ is a positive integer. Let $X_1, \ldots, X_n$ be i.i.d. real-valued random vectors drawn from a distribution supported on $\mathbb{R}^d$. Given every $u \in \mathcal{S}^{d-1}$, define the projected CDF and empirical CDF on the direction $u$ as $F(t; u) = \mathbb{P}(X^\top u \leq t)$ and $F_n(t; u) = \frac{1}{n} \sum_{i \in [n]} {\mathds{1}}(X_i^\top u \leq t)$, respectively. Then for any $\alpha \in (0,1)$,
	\begin{equation*}
		\mathbb{P}\left( \sup_{t \in \mathbb{R}, u \in \mathcal{S}^{d-1}} |F_n(t;u) - F(t;u)| > 150 \sqrt{ \frac{(d+1)}{n} } + \sqrt{ \frac{\log(1/\alpha)}{2n} } \right) \leq \alpha.
	\end{equation*}

\label{lm:normal-quantile}
	Let $\Phi(\cdot)$ be the CDF of the standard Gaussian distribution. Given some $q < 1/2$, $x = \Phi^{-1}(1 - q)$. Suppose $x \geq 2$, then
	\begin{equation*}
	\begin{split}
		\frac{1}{2} \sqrt{\log( 1/q ) } \leq \sqrt{\log(1/ (\sqrt{2\pi}q))}	\leq x \leq  \sqrt{2 \log( 1/q ) }\quad  \text{ and }\quad \frac{1}{\sqrt{2\pi}} {\rm{exp}}(-x^2) \leq q \leq \frac{1}{2\sqrt{2\pi}} {\rm{exp}}(-x^2/2).
	\end{split}
	\end{equation*}

By the definition of $x$, we have $\int_x^\infty \frac{1}{\sqrt{2\pi}} {\rm{exp}}(-t^2/2) dt = q$. In addition, for any $x > 0$ (see Theorem 1.2.3 in \cite{durrett2019probability}),
	\begin{equation}
		(\frac{1}{x} - \frac{1}{x^3}) {\rm{exp}}(-x^2/2) \leq \int_{x}^{\infty} {\rm{exp}}( - t^2/2 ) dt \leq \frac{1}{x} {\rm{exp}}(-x^2/2).
	\end{equation}
	Since $x \geq 2$, $\frac{1}{x} - \frac{1}{x^3} \geq \frac{1}{x}( 1- \frac{1}{4} ) = \frac{3}{4x}$ and $\frac{1}{x}\leq \frac{1}{2}$. At the same time, it is easy to check $\frac{3}{4x} {\rm{exp}}(-x^2/2) \geq {\rm{exp}}(-x^2)$ for all $x \geq 2$. Thus, we have
	\begin{equation*}
		\frac{1}{\sqrt{2\pi}} {\rm{exp}}(-x^2) \leq q \leq \frac{1}{2\sqrt{2\pi}} {\rm{exp}}(-x^2/2)
	\end{equation*} holds for any $x \geq 2$. Thus
	\begin{equation*}
 	\frac{1}{2} \sqrt{\log( 1/q ) } \overset{(a)}\leq \sqrt{\log(1/ (\sqrt{2\pi}q))}	\leq x \leq \sqrt{2 \log( 1/(2 \sqrt{2\pi} q) ) } \leq \sqrt{2 \log( 1/q ) },
	\end{equation*} where in (a) we use the fact $q \leq 0.023$ when $x \geq 2$, so the inequality always holds when $x \geq 2$.

(Bernstein's inequality) \label{lm:Binomial-prop} Given any positive integer $n$, $\alpha \in (0,1)$ and $0\leq p \leq 1$,
	\begin{equation*}
		\mathbb{P}\left(|\textnormal{Binomial}(n,p) - np| \geq \frac{4\log(2/\alpha) }{3}  \vee 2\sqrt{ p(1-p)n\log(2/\alpha) } \right) \leq \alpha.
	\end{equation*} 
    Since $ \frac{np(1-p)}{C} + C \log(2/\alpha) \geq \frac{4\log(2/\alpha) }{3}  \vee 2\sqrt{ p(1-p)n\log(2/\alpha) }  $ holds for any $C \geq 4/3$, the inequality above holds if we replace $\frac{4\log(2/\alpha) }{3}  \vee 2\sqrt{ p(1-p)n\log(2/\alpha) } $ by $ \frac{np(1-p)}{C} + C \log(2/\alpha) $ for any $C \geq 4/3$.

\label{lm:NGCA}
	Let $m$ be any positive integer. If the distribution $A$ over $\mathbb{R}$ agrees with the first $m$ moments of $N(0,1)$, then for all $u, u' \in \mathcal{S}^{d-1}$, we have that 
	\begin{equation*}
		\Big| \int \frac{P^A_u(x) P^A_{u'}(x)}{\phi_d(x) } dx - 1 \Big| \leq |u^\top u'|^{m+1} \chi^2(A, N(0,1)).
	\end{equation*}

\label{lm:polynomial-matching-bound}
	Let $C > 0$ and $m \in \mathbb{Z}_+$. For any $a_0, a_1, \dots, a_m \in \mathbb{R}$, there exists a unique degree at most $m$ polynomial $p \colon \mathbb{R} \to \mathbb{R}$ such that for each integer $0 \le t \le m$ we have that
\begin{equation}
\int_{-C}^{C} p(x)x^t dx = a_t \,.
\end{equation}
Furthermore, for each $x \in [-C, C]$ we have that $|p(x)| \le   2m^2  \sum_{k=0}^{m} \left(2e\right)^k \left(  \max_{0 \leq t \leq k}|a_t| C^{-t-1} \right)$.

\label{lm:legendre-polynomial}
	The Legendre polynomial, $L_k(x)$, for $k \in \mathbb{Z}_{+}$, satisfies the following properties:
	\begin{itemize}
		\item (i) $L_k(x)$ is a degree-$k$ polynomial, $L_0(x) = 1$ and $L_1(x) = x$.
		\item (ii) $\int_{-1}^1 L^2_i(x) d x = \frac{2}{2i + 1}$ for all $i \geq 0$ and $\int_{-1}^1 L_i(x) L_j(x) d x = 0$ for all $i, j \geq 0, i \neq j$.
		\item (iii) $|L_k(x)| \leq 1$ for all $|x| \leq 1$.
		\item (iv) $L_k(x) = (-1)^k L_k(-x)$.
		\item (v) $L_k(x) = \frac{1}{2^k} \sum_{i=0}^{ \lfloor k/2 \rfloor } (-1)^i {k \choose i} {2k-2i \choose k} x^{k-2i}$.
		\item (vi) $\int_{-1}^1 |L_k(x)|dx \leq O(1/\sqrt{k})$.
	\end{itemize}

\label{lm:t-epsilon-bound}
	For any $\epsilon_{\max} < 1/2$, positive integer $n$ and $\alpha \in (0,1)$ such that $n/(d + \log(1/\alpha))$ is sufficiently large, then for all $\epsilon \in [0, \epsilon_{\max}]$,
	\begin{equation*}
		1/t_{\epsilon} \asymp \frac{1}{\sqrt{\log(1/\epsilon)}} + \frac{1}{\sqrt{\log( n/\log(1/\alpha) )}} + \frac{1}{\sqrt{\log( n/d )}},
	\end{equation*} where $t_{\epsilon} = \Phi^{-1}\left( 1- \epsilon - 300 \sqrt{ \frac{d}{n} } - \sqrt{ \frac{\log(1/\alpha)}{n} }  \right)$.

We divide the proof into two cases. First, when $\epsilon \in [0.01, \epsilon_{\max}]$, $1/t_{\epsilon}$ is of constant level, so the result follows. 
	At the same time, when $\epsilon \in [0,  0.01]$, we have $t_{\epsilon} \geq 2$ when $n/(d + \log(1/\alpha))$ is sufficiently large, by Lemma \ref{lm:normal-quantile}, we have
	\begin{equation*}
	\begin{split}
		t_{\epsilon} & \asymp  \sqrt{ \log\left( \frac{1}{\epsilon + \sqrt{ \frac{d}{n} } + \sqrt{ \frac{\log(1/\alpha)}{n} }}  \right)  } \\
		& \asymp \sqrt{ \log\left( 1/\epsilon  \right)} \wedge \sqrt{ \log\left(n/d \right) } \wedge \sqrt{ \log\left(\frac{n}{\log \left( \frac{1}{\alpha} \right)} \right) }.
	\end{split}
	\end{equation*} Thus, $1/t_{\epsilon} \asymp \frac{1}{\sqrt{\log(1/\epsilon)}} + \frac{1}{\sqrt{\log( n/d )}} + \frac{1}{\sqrt{\log( n/\log(1/\alpha) )}}$.
